PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,     -- sha256 hex dari token opaque 32 byte
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at INTEGER NOT NULL,
  revoked_at INTEGER,
  ip TEXT,
  ua TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE auth_codes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tg_id TEXT NOT NULL,
  code_hash TEXT NOT NULL,          -- sha256 hex dari kode 6 digit
  purpose TEXT NOT NULL CHECK (purpose IN ('reset','link','otp')),
  expires_at INTEGER NOT NULL,
  used_at INTEGER,
  attempts INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE login_audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tg_id TEXT NOT NULL,
  ip TEXT,
  ua TEXT,
  sukses INTEGER NOT NULL DEFAULT 0,
  alasan TEXT,
  at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL DEFAULT '',
  updated_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE idempotency_keys (
  key TEXT PRIMARY KEY,
  at INTEGER NOT NULL DEFAULT (unixepoch())
);
ANALYZE sqlite_schema;
CREATE TABLE IF NOT EXISTS "warehouses" (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  nama TEXT NOT NULL,
  aktif INTEGER NOT NULL DEFAULT 1 CHECK (aktif IN (0,1)),
  urutan INTEGER NOT NULL DEFAULT 0,
  is_online INTEGER NOT NULL DEFAULT 0 CHECK (is_online IN (0,1)),
  created_at INTEGER,
  created_by TEXT,
  updated_at INTEGER,
  updated_by TEXT,
  nonaktif_at INTEGER,
  nonaktif_by TEXT
, kledo_id INTEGER, kledo_synced_at INTEGER);
CREATE TABLE products (
  sku TEXT PRIMARY KEY,
  nama_accurate TEXT NOT NULL,
  nama_accurate_normalized TEXT NOT NULL DEFAULT '',
  hpp INTEGER,
  hpp_baru INTEGER,
  is_online_product INTEGER NOT NULL DEFAULT 0 CHECK (is_online_product IN (0,1)),
  online_updated_by TEXT,
  updated_at INTEGER,
  stok_min INTEGER,
  last_stock_updated INTEGER,
  last_stock_updated_by TEXT,
  last_synced_at INTEGER,
  last_synced_value INTEGER
, kategori_shopee TEXT, kategori TEXT, tier_override TEXT, pre_order INTEGER NOT NULL DEFAULT 0, ukuran_khusus INTEGER NOT NULL DEFAULT 0, go_override TEXT, kledo_synced_at INTEGER);
CREATE TABLE product_variants (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sku TEXT NOT NULL REFERENCES products(sku) ON DELETE CASCADE,
  variasi TEXT NOT NULL,
  UNIQUE(sku, variasi)
);
CREATE TABLE product_search_keywords (
  sku TEXT NOT NULL REFERENCES products(sku) ON DELETE CASCADE,
  keyword TEXT NOT NULL,
  PRIMARY KEY (sku, keyword)
);
CREATE TABLE mp_products (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sku TEXT NOT NULL REFERENCES products(sku) ON DELETE CASCADE,
  marketplace TEXT NOT NULL DEFAULT 'shopee',
  nama_mp TEXT,
  harga_jual_mp INTEGER
);
CREATE TABLE stock_by_bin (
  sku TEXT NOT NULL REFERENCES products(sku) ON DELETE CASCADE,
  warehouse_id TEXT NOT NULL REFERENCES warehouses(id),
  qty INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (sku, warehouse_id)
);
CREATE TABLE transfers (
  id TEXT PRIMARY KEY,
  dari_warehouse_id TEXT NOT NULL REFERENCES warehouses(id),
  status TEXT NOT NULL DEFAULT 'menunggu' CHECK (status IN ('menunggu','disetujui','ditolak','dibatalkan','dikirim','selesai')),
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  created_by TEXT,
  catatan TEXT
);
CREATE TABLE transfer_destinations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  transfer_id TEXT NOT NULL REFERENCES transfers(id) ON DELETE CASCADE,
  idx_tujuan INTEGER NOT NULL,
  tipe TEXT NOT NULL DEFAULT 'gudang',
  dest_warehouse_id TEXT REFERENCES warehouses(id),
  nama_snapshot TEXT,
  status TEXT NOT NULL DEFAULT 'menunggu' CHECK (status IN ('menunggu','diterima','tidak_terima','ditolak','ditutup')),
  status_kirim TEXT NOT NULL DEFAULT 'menunggu' CHECK (status_kirim IN ('menunggu','disetujui','dikirim')),
  user_penerima_id TEXT,
  user_penerima_nama TEXT,
  notifikasi_terkirim INTEGER CHECK (notifikasi_terkirim IN (0,1)),
  disetujui_at INTEGER, disetujui_oleh TEXT,
  dikirim_at INTEGER, dikirim_oleh TEXT,
  ditolak_at INTEGER, ditolak_oleh TEXT,
  diterima_at INTEGER, diterima_oleh TEXT,
  tidak_terima_at INTEGER, tidak_terima_oleh TEXT,
  ditutup_at INTEGER, ditutup_oleh TEXT,
  catatan_alasan TEXT,
  UNIQUE(transfer_id, idx_tujuan)
);
CREATE TABLE transfer_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  destination_id INTEGER NOT NULL REFERENCES transfer_destinations(id) ON DELETE CASCADE,
  sku TEXT NOT NULL REFERENCES products(sku),
  nama TEXT,
  variasi TEXT,
  qty INTEGER NOT NULL CHECK (qty >= 1)
);
CREATE TABLE transfer_status_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  transfer_id TEXT NOT NULL REFERENCES transfers(id) ON DELETE CASCADE,
  status TEXT NOT NULL,
  oleh TEXT,
  at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE stock_counts (
  id TEXT PRIMARY KEY,
  warehouse_id TEXT NOT NULL REFERENCES warehouses(id),
  status TEXT NOT NULL DEFAULT 'menunggu_approval' CHECK (status IN ('menunggu_approval','disetujui','ditolak')),
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  created_by TEXT,
  catatan TEXT,
  disetujui_oleh TEXT,
  disetujui_at INTEGER,
  ditolak_oleh TEXT,
  ditolak_at INTEGER,
  freeze INTEGER NOT NULL DEFAULT 0 CHECK (freeze IN (0,1))
);
CREATE TABLE count_lines (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  count_id TEXT NOT NULL REFERENCES stock_counts(id) ON DELETE CASCADE,
  sku TEXT NOT NULL REFERENCES products(sku),
  qty_sistem INTEGER,
  qty_fisik INTEGER NOT NULL,
  selisih INTEGER NOT NULL,
  belum_terdaftar INTEGER NOT NULL DEFAULT 0 CHECK (belum_terdaftar IN (0,1))
);
CREATE TABLE count_status_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  count_id TEXT NOT NULL REFERENCES stock_counts(id) ON DELETE CASCADE,
  status TEXT NOT NULL,
  oleh TEXT,
  at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE daily_requests (
  tanggal TEXT PRIMARY KEY,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','diproses','selesai')),
  created_at INTEGER,
  form_dibuat_at INTEGER,
  form_dibuat_by TEXT,
  selesai_at INTEGER,
  selesai_by TEXT,
  updated_at INTEGER,
  updated_by TEXT
);
CREATE TABLE daily_request_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tanggal TEXT NOT NULL REFERENCES daily_requests(tanggal) ON DELETE CASCADE,
  sku TEXT NOT NULL REFERENCES products(sku),
  nama TEXT,
  variasi TEXT NOT NULL DEFAULT '-',
  qty INTEGER NOT NULL,
  buffer INTEGER NOT NULL DEFAULT 0 CHECK (buffer IN (0,1)),
  status TEXT NOT NULL DEFAULT 'diminta' CHECK (status IN ('diminta','datang')),
  qty_diminta INTEGER,
  qty_datang INTEGER,
  datang_at INTEGER,
  datang_by TEXT,
  UNIQUE(tanggal, sku, variasi, buffer, status)
);
CREATE TABLE daily_request_changes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tanggal TEXT NOT NULL REFERENCES daily_requests(tanggal) ON DELETE CASCADE,
  key_item TEXT NOT NULL,
  qty_lama INTEGER,
  qty_baru INTEGER,
  oleh TEXT,
  at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE access_requests (
  tg_id INTEGER PRIMARY KEY,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','revoked')),
  requested_at INTEGER,
  telegram_username TEXT,
  telegram_display_name TEXT,
  rejected_until INTEGER,
  resolved_by TEXT,
  resolved_at INTEGER,
  revoked_by TEXT,
  revoked_at INTEGER
);
CREATE TABLE bot_sessions (
  tg_id INTEGER PRIMARY KEY,
  history_json TEXT NOT NULL DEFAULT '[]',
  last_updated INTEGER,
  pending_action_json TEXT,
  pending_batch_action_json TEXT,
  pending_opname_json TEXT,
  pending_picking_list_json TEXT,
  pending_sync_stok_json TEXT,
  pending_konfirmasi_cakupan_json TEXT
);
CREATE TABLE keyword_notes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  raw_text TEXT NOT NULL UNIQUE COLLATE NOCASE,
  interpreted_as TEXT NOT NULL CHECK (interpreted_as IN ('STOK','MINTA','MINTA_SISA')),
  confidence TEXT NOT NULL DEFAULT 'guessed' CHECK (confidence IN ('guessed','confirmed')),
  usage_count INTEGER NOT NULL DEFAULT 1,
  first_seen INTEGER,
  last_used INTEGER,
  confirmed_by TEXT,
  confirmed_at INTEGER
);
CREATE TABLE product_changes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sku TEXT NOT NULL REFERENCES products(sku),
  field TEXT NOT NULL,
  lama TEXT,
  baru TEXT,
  oleh TEXT,
  at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE admin_role_changes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tg_id TEXT NOT NULL,
  role_lama TEXT,
  role_baru TEXT,
  catatan TEXT,
  oleh TEXT,
  at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE guards (
  scope TEXT NOT NULL,
  key TEXT NOT NULL,
  payload_json TEXT,
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  PRIMARY KEY (scope, key)
);
CREATE TABLE notify_queue (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  kind TEXT NOT NULL CHECK (kind IN ('problem','report','info')),
  payload TEXT NOT NULL,
  target_user INTEGER,
  target_group INTEGER,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  sent_at INTEGER,
  attempts INTEGER NOT NULL DEFAULT 0,
  last_error TEXT
);
CREATE TABLE groups (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  chat_id INTEGER UNIQUE NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  chat_type TEXT NOT NULL DEFAULT 'group',
  status TEXT NOT NULL DEFAULT 'detected' CHECK (status IN ('detected','active','left')),
  notify_problem INTEGER NOT NULL DEFAULT 0 CHECK (notify_problem IN (0,1)),
  added_at INTEGER NOT NULL DEFAULT (unixepoch()),
  enabled_by TEXT,
  enabled_at INTEGER,
  last_ok_at INTEGER,
  last_error TEXT,
  last_error_at INTEGER
);
CREATE TABLE import_batches (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tipe TEXT NOT NULL,
  file TEXT,
  total INTEGER NOT NULL DEFAULT 0,
  sukses INTEGER NOT NULL DEFAULT 0,
  gagal INTEGER NOT NULL DEFAULT 0,
  gudang_id TEXT NOT NULL DEFAULT 'ONLINE',
  payload_json TEXT NOT NULL DEFAULT '[]',
  status TEXT NOT NULL DEFAULT 'preview' CHECK (status IN ('preview','done','batal')),
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  by TEXT
);
CREATE TABLE import_errors (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  batch_id INTEGER NOT NULL REFERENCES import_batches(id) ON DELETE CASCADE,
  baris INTEGER NOT NULL,
  pesan TEXT NOT NULL
);
CREATE TABLE orders (
  marketplace TEXT NOT NULL,
  no_pesanan TEXT NOT NULL,
  tanggal INTEGER NOT NULL,
  buyer TEXT NOT NULL DEFAULT '',
  status_fulfill TEXT NOT NULL DEFAULT 'pending'
    CHECK (status_fulfill IN ('pending','pack','kirim','selesai','batal')),
  pajak_pph INTEGER NOT NULL DEFAULT 1 CHECK (pajak_pph IN (0,1)),
  pajak_ppn_persen INTEGER NOT NULL DEFAULT 0, stok_dikurangi INTEGER NOT NULL DEFAULT 0 CHECK (stok_dikurangi IN (0,1)), no_resi TEXT NOT NULL DEFAULT '', asal_import TEXT NOT NULL DEFAULT '', booking_sn TEXT, opsi_kirim TEXT NOT NULL DEFAULT '', antar_ke TEXT NOT NULL DEFAULT '', status_mp TEXT NOT NULL DEFAULT '', item_json TEXT NOT NULL DEFAULT '[]', batch_import INTEGER, jasa_kirim TEXT NOT NULL DEFAULT '', tipe_layanan TEXT NOT NULL DEFAULT '', cod INTEGER NOT NULL DEFAULT 0, preorder INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (marketplace, no_pesanan)
);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE laba_harian (
  tanggal TEXT PRIMARY KEY,
  marketplace TEXT NOT NULL DEFAULT 'shopee',
  jml_order INTEGER NOT NULL DEFAULT 0,
  jml_baris INTEGER NOT NULL DEFAULT 0,
  omzet INTEGER NOT NULL DEFAULT 0,
  hpp INTEGER NOT NULL DEFAULT 0,
  biaya INTEGER NOT NULL DEFAULT 0,
  laba INTEGER NOT NULL DEFAULT 0,
  tolak_json TEXT NOT NULL DEFAULT '[]',
  file TEXT NOT NULL DEFAULT '',
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  by TEXT
, rincian_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS "users" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tg_id TEXT NOT NULL UNIQUE,
  username TEXT,
  display_name TEXT NOT NULL DEFAULT '',
  password_hash TEXT,
  password_set_at INTEGER,
  role TEXT NOT NULL DEFAULT 'staff' CHECK (role IN ('owner','admin','staff','guest')),
  active INTEGER NOT NULL DEFAULT 1,
  notify_problem INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  jabatan TEXT,
  added_at INTEGER,
  approved_by TEXT,
  role_updated_at INTEGER,
  role_updated_by TEXT,
  gudang_updated_at INTEGER,
  gudang_updated_by TEXT,
  jabatan_updated_at INTEGER,
  jabatan_updated_by TEXT
);
CREATE TABLE user_warehouses (
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  warehouse_id INTEGER NOT NULL REFERENCES warehouses(id) ON DELETE CASCADE,
  PRIMARY KEY (user_id, warehouse_id)
);
CREATE TABLE IF NOT EXISTS "order_fees" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  marketplace TEXT NOT NULL,
  no_pesanan TEXT NOT NULL,
  jenis TEXT NOT NULL CHECK (jenis IN ('admin','service','komisi','ongkir','voucher','affiliate','iklan','lain')),
  basis TEXT NOT NULL CHECK (basis IN ('flat','persen')),
  nilai REAL NOT NULL DEFAULT 0,
  amount INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (marketplace, no_pesanan) REFERENCES orders(marketplace, no_pesanan) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "mp_fee_presets" (
  marketplace TEXT NOT NULL,
  jenis TEXT NOT NULL,
  basis TEXT NOT NULL CHECK (basis IN ('flat','persen')),
  nilai REAL NOT NULL DEFAULT 0,
  PRIMARY KEY (marketplace, jenis)
);
CREATE TABLE seller_presets (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nama TEXT NOT NULL,
  marketplace TEXT NOT NULL DEFAULT 'shopee',
  status_toko TEXT NOT NULL CHECK (status_toko IN ('non_star','star','star_plus')),
  aktif INTEGER NOT NULL DEFAULT 1,
  dibuat_at INTEGER NOT NULL DEFAULT (unixepoch()),
  diubah_at INTEGER NOT NULL DEFAULT (unixepoch()),
  dihapus_at INTEGER
, status_berlaku_sejak TEXT);
CREATE TABLE fee_rules (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  preset_id INTEGER NOT NULL REFERENCES seller_presets(id) ON DELETE CASCADE,
  jenis TEXT NOT NULL,
  kategori TEXT NOT NULL DEFAULT '*',
  status_toko TEXT,
  basis TEXT NOT NULL CHECK (basis IN ('persen','flat')),
  unit TEXT NOT NULL DEFAULT 'per_baris' CHECK (unit IN ('per_baris','per_order')),
  nilai REAL NOT NULL CHECK (nilai >= 0),
  plafon INTEGER,
  priority INTEGER NOT NULL DEFAULT 0,
  valid_from TEXT NOT NULL,
  valid_to TEXT,
  aktif INTEGER NOT NULL DEFAULT 1,
  sumber TEXT,
  status_verifikasi TEXT NOT NULL DEFAULT 'belum_diverifikasi'
    CHECK (status_verifikasi IN ('terverifikasi','belum_diverifikasi')),
  catatan TEXT,
  dibuat_at INTEGER NOT NULL DEFAULT (unixepoch())
, kode_program TEXT, ukuran TEXT, plafon_per_qty INTEGER, syarat_json TEXT, verifikasi TEXT NOT NULL DEFAULT 'belum');
CREATE TABLE laba_snapshot (
  preset_id INTEGER NOT NULL REFERENCES seller_presets(id) ON DELETE CASCADE,
  tanggal TEXT NOT NULL,
  jml_order INTEGER NOT NULL DEFAULT 0,
  jml_baris INTEGER NOT NULL DEFAULT 0,
  omzet INTEGER NOT NULL DEFAULT 0,
  hpp INTEGER NOT NULL DEFAULT 0,
  biaya INTEGER NOT NULL DEFAULT 0,
  laba INTEGER NOT NULL DEFAULT 0,
  tolak_json TEXT NOT NULL DEFAULT '[]',
  rincian_json TEXT NOT NULL DEFAULT '[]',
  peringatan_json TEXT NOT NULL DEFAULT '[]',
  file TEXT NOT NULL DEFAULT '',
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  by TEXT, pajak INTEGER NOT NULL DEFAULT 0, no_json TEXT NOT NULL DEFAULT '[]',
  PRIMARY KEY (preset_id, tanggal)
);
CREATE TABLE kategori_tarif (
  kategori_path TEXT PRIMARY KEY,
  tier TEXT NOT NULL,
  grup_go TEXT,
  sumber TEXT,
  verifikasi TEXT NOT NULL DEFAULT 'belum'
    CHECK (verifikasi IN ('resmi','resmi_cuplikan','sekunder','belum')),
  diubah_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE tier_admin (
  tier TEXT PRIMARY KEY,
  persen_dasar REAL,
  diskon_persen REAL NOT NULL DEFAULT 0,
  persen_final REAL NOT NULL,
  verifikasi TEXT NOT NULL DEFAULT 'belum'
);
CREATE TABLE program_katalog (
  kode_program TEXT PRIMARY KEY,
  nama TEXT NOT NULL,
  opsional INTEGER NOT NULL DEFAULT 1,
  catatan TEXT
);
CREATE TABLE preset_program (
  preset_id INTEGER NOT NULL REFERENCES seller_presets(id) ON DELETE CASCADE,
  kode_program TEXT NOT NULL REFERENCES program_katalog(kode_program),
  aktif INTEGER NOT NULL DEFAULT 0,
  aktif_sejak TEXT,
  aktif_sampai TEXT,
  PRIMARY KEY (preset_id, kode_program)
);
CREATE TABLE ads_harian (
  preset_id INTEGER NOT NULL REFERENCES seller_presets(id) ON DELETE CASCADE,
  tanggal TEXT NOT NULL,
  biaya_iklan_bersih INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (preset_id, tanggal)
);
CREATE TABLE preset_penghitung (
  preset_id INTEGER PRIMARY KEY REFERENCES seller_presets(id) ON DELETE CASCADE,
  pesanan_selesai_kumulatif INTEGER NOT NULL DEFAULT 0,
  bergabung_sejak TEXT,
  upload_produk_pertama TEXT
);
CREATE TABLE laba_order (
  preset_id INTEGER NOT NULL REFERENCES seller_presets(id) ON DELETE CASCADE,
  no_pesanan TEXT NOT NULL,
  tanggal_snapshot TEXT NOT NULL,
  tanggal_pesanan TEXT,
  status_pesanan TEXT NOT NULL DEFAULT '',
  omzet INTEGER NOT NULL DEFAULT 0,
  hpp INTEGER NOT NULL DEFAULT 0,
  biaya INTEGER NOT NULL DEFAULT 0,
  pajak INTEGER NOT NULL DEFAULT 0,
  laba INTEGER NOT NULL DEFAULT 0,
  hash_baris TEXT NOT NULL DEFAULT '',
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  PRIMARY KEY (preset_id, no_pesanan)
);
CREATE TABLE advance_bookings (
  booking_sn TEXT PRIMARY KEY,
  no_resi TEXT DEFAULT '',
  sku TEXT NOT NULL REFERENCES products(sku),
  variasi TEXT DEFAULT '',
  nama_produk TEXT DEFAULT '',
  opsi_kirim TEXT DEFAULT '',
  antar_ke TEXT DEFAULT '',
  booking_at TEXT,
  batas_kirim TEXT,
  qty INTEGER DEFAULT 1,
  status TEXT DEFAULT 'menunggu'
    CHECK (status IN ('menunggu','terkirim','batal','timeout')),
  batch_import INTEGER,
  dikirim_at INTEGER,
  dikirim_oleh TEXT,
  at INTEGER DEFAULT (unixepoch())
);
CREATE TABLE import_files (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tipe TEXT NOT NULL,
  file TEXT NOT NULL,
  file_hash TEXT NOT NULL,
  no_json TEXT DEFAULT '[]',
  batch_id INTEGER,
  at INTEGER DEFAULT (unixepoch()),
  by TEXT
);
CREATE TABLE sku_belum_mp (
  nama_shopee TEXT NOT NULL,
  variasi TEXT DEFAULT '',
  order_ref TEXT NOT NULL,
  sejak TEXT NOT NULL,
  at INTEGER DEFAULT (unixepoch()),
  by TEXT, sumber TEXT DEFAULT 'order', sku_asal TEXT DEFAULT '', qty_total INTEGER DEFAULT 0,
  PRIMARY KEY (nama_shopee, variasi)
);
CREATE TABLE resi_grup (
  no_resi TEXT PRIMARY KEY,
  no_json TEXT NOT NULL DEFAULT '[]',
  jumlah_order INTEGER NOT NULL DEFAULT 1 CHECK (jumlah_order >= 1),
  tipe_pesanan TEXT NOT NULL DEFAULT 'tunggal'
    CHECK (tipe_pesanan IN ('tunggal','gabungan')),
  jasa_kirim TEXT NOT NULL DEFAULT '',
  tipe_layanan TEXT NOT NULL DEFAULT '',
  cod INTEGER NOT NULL DEFAULT 0,
  preorder INTEGER NOT NULL DEFAULT 0,
  sesuai_kriteria INTEGER NOT NULL DEFAULT 1,
  at INTEGER DEFAULT (unixepoch())
);
CREATE TABLE order_items (
  marketplace TEXT NOT NULL,
  no_pesanan TEXT NOT NULL,
  sku TEXT NOT NULL REFERENCES products(sku),
  variasi TEXT DEFAULT '',
  nama_shopee TEXT DEFAULT '',
  qty INTEGER NOT NULL CHECK (qty >= 1),
  harga_satuan INTEGER NOT NULL CHECK (harga_satuan >= 0),
  hpp_snapshot INTEGER DEFAULT 0,
  subtotal INTEGER DEFAULT 0, sku_asal TEXT DEFAULT '', perlu_sku INTEGER NOT NULL DEFAULT 0 CHECK (perlu_sku IN (0,1)),
  PRIMARY KEY (marketplace, no_pesanan, sku, variasi),
  FOREIGN KEY (marketplace, no_pesanan) REFERENCES orders(marketplace, no_pesanan) ON DELETE CASCADE
);
CREATE TABLE stock_moves (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ref_client_id TEXT UNIQUE,
  sku TEXT NOT NULL REFERENCES products(sku),
  nama_terbaca TEXT,
  variasi TEXT,
  qty INTEGER,
  jenis TEXT NOT NULL CHECK (jenis IN ('keluar_resi','opname','restock','koreksi_manual','sync_confirmed','OPENING','TRANSFER_IN','TRANSFER_OUT','jual_mp','retur_mp','kirim_advance')),
  gudang_id TEXT REFERENCES warehouses(id),
  action_type TEXT,
  qty_sistem INTEGER,
  qty_fisik INTEGER,
  selisih INTEGER,
  penanda TEXT,
  catatan TEXT,
  source TEXT CHECK (source IN ('screenshot','manual_chat','manual_chat_batch','manual_chat_produk_baru','manual_chat_batch_produk_baru','sync','web_dashboard')),
  status TEXT NOT NULL DEFAULT 'processed' CHECK (status IN ('processed','pending_request','pending_confirmation')),
  created_by TEXT,
  created_by_username TEXT,
  created_by_name TEXT,
  requested_by TEXT,
  requested_by_username TEXT,
  requested_by_name TEXT,
  confirmed_by TEXT,
  resolved_by TEXT,
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  by TEXT,
  bin_id INTEGER,
  hpp_snapshot INTEGER
);
CREATE TABLE ai_kredensial (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  provider    TEXT NOT NULL,                 -- groq|gemini|kenari|openai|openrouter
  label       TEXT NOT NULL DEFAULT '',      -- nama bebas, mis. "Groq utama"
  ciphertext  TEXT NOT NULL,                 -- base64
  iv          TEXT NOT NULL,                 -- base64, 12 byte
  tag         TEXT NOT NULL,                 -- base64, 16 byte
  /** 4 karakter terakhir plaintext, untuk ditampilkan sebagai mask (mis. "••••3f2a"). */
  ujung       TEXT NOT NULL DEFAULT '',
  aktif       INTEGER NOT NULL DEFAULT 1,
  dibuat_at   INTEGER NOT NULL DEFAULT (unixepoch()),
  dibuat_oleh TEXT,
  uji_at      INTEGER,                       -- terakhir diuji
  uji_hasil   TEXT                           -- JSON: {ok, latencyMs, model, error}
, base_url TEXT NOT NULL DEFAULT '');
CREATE TABLE ai_model (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  provider    TEXT NOT NULL,
  model_id    TEXT NOT NULL,                 -- mis. openai/gpt-oss-120b
  label       TEXT NOT NULL DEFAULT '',
  jenis       TEXT NOT NULL DEFAULT 'teks',  -- teks|gambar|vision
  aktif       INTEGER NOT NULL DEFAULT 1,
  ditambah_at INTEGER NOT NULL DEFAULT (unixepoch()), modal_masuk TEXT NOT NULL DEFAULT '', modal_keluar TEXT NOT NULL DEFAULT '', reasoning_skema TEXT NOT NULL DEFAULT '', reasoning_pilihan TEXT NOT NULL DEFAULT '', reasoning_hilir INTEGER NOT NULL DEFAULT 0, sumber TEXT NOT NULL DEFAULT 'manual',
  UNIQUE (provider, model_id)
);
CREATE TABLE ai_preset_prompt (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  nama      TEXT NOT NULL,
  kategori  TEXT NOT NULL DEFAULT 'produk',  -- produk|latar|gaya|lain
  prompt    TEXT NOT NULL,
  urutan    INTEGER NOT NULL DEFAULT 0,
  aktif     INTEGER NOT NULL DEFAULT 1,
  dibuat_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE ai_tool (
  nama             TEXT PRIMARY KEY,         -- mis. "cekStok"
  label            TEXT NOT NULL,
  deskripsi        TEXT NOT NULL DEFAULT '',
  jenis            TEXT NOT NULL DEFAULT 'baca',  -- baca|tulis
  perlu_konfirmasi INTEGER NOT NULL DEFAULT 0,
  aktif            INTEGER NOT NULL DEFAULT 1,
  urutan           INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE ai_tool_kata (
  id      INTEGER PRIMARY KEY AUTOINCREMENT,
  tool    TEXT NOT NULL,
  kata    TEXT NOT NULL,                     -- satu kata/frasa, lowercase
  urutan  INTEGER NOT NULL DEFAULT 0,
  aktif   INTEGER NOT NULL DEFAULT 1,
  UNIQUE (tool, kata)
);
CREATE TABLE ai_pemakaian (
  tanggal      TEXT NOT NULL,                -- YYYY-MM-DD (WIB)
  provider     TEXT NOT NULL,
  model        TEXT NOT NULL,
  jenis        TEXT NOT NULL,                -- teks|gambar|vision
  panggilan    INTEGER NOT NULL DEFAULT 0,
  token_masuk  INTEGER NOT NULL DEFAULT 0,
  token_keluar INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (tanggal, provider, model, jenis)
);
CREATE TABLE ai_gambar_setting (
  tg_id         TEXT PRIMARY KEY,
  provider      TEXT NOT NULL DEFAULT 'gemini',
  model_id      TEXT NOT NULL DEFAULT '',      -- '' = model gambar dari pengaturan global
  reasoning     TEXT NOT NULL DEFAULT '',      -- '' = default provider; nilai sah dari ai_model.reasoning_pilihan
  aspek_rasio   TEXT NOT NULL DEFAULT '1:1',
  jumlah        INTEGER NOT NULL DEFAULT 1,
  diperbarui_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE kledo_kredensial (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  subdomain   TEXT NOT NULL,                 -- {subdomain}.api.kledo.com, mis. cv-hanaa-jaya
  label       TEXT NOT NULL DEFAULT '',      -- nama bebas, mis. "Kledo produksi"
  ciphertext  TEXT NOT NULL,                 -- base64
  iv          TEXT NOT NULL,                 -- base64, 12 byte
  tag         TEXT NOT NULL,                 -- base64, 16 byte
  ujung       TEXT NOT NULL DEFAULT '',      -- 4 karakter terakhir plaintext untuk mask
  aktif       INTEGER NOT NULL DEFAULT 1 CHECK (aktif IN (0,1)),
  dibuat_at   INTEGER NOT NULL DEFAULT (unixepoch()),
  dibuat_oleh TEXT,
  uji_at      INTEGER,                       -- terakhir diuji
  uji_ok      INTEGER CHECK (uji_ok IN (0,1)), uji_pesan TEXT, -- hasil uji terakhir
  UNIQUE(subdomain)
);
CREATE TABLE kledo_map (
  jenis           TEXT NOT NULL CHECK (jenis IN ('produk','gudang')),
  kledo_id        TEXT NOT NULL,
  lokal_id        TEXT NOT NULL,             -- products.sku atau warehouses.id
  nama_snapshot   TEXT,                      -- nama saat terakhir dilihat (untuk diagnosis)
  terakhir_dilihat INTEGER NOT NULL DEFAULT (unixepoch()),
  PRIMARY KEY (jenis, kledo_id)
);
CREATE TABLE kledo_sync (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  mulai_at       INTEGER NOT NULL DEFAULT (unixepoch()),
  selesai_at     INTEGER,
  jenis          TEXT NOT NULL DEFAULT 'semua',   -- gudang|produk|stok|semua
  pemicu         TEXT NOT NULL DEFAULT 'manual' CHECK (pemicu IN ('manual','jadwal')),
  status         TEXT NOT NULL DEFAULT 'jalan' CHECK (status IN ('jalan','sukses','sebagian','gagal')),
  gudang_baru    INTEGER NOT NULL DEFAULT 0,
  gudang_ubah    INTEGER NOT NULL DEFAULT 0,
  produk_baru    INTEGER NOT NULL DEFAULT 0,
  produk_ubah    INTEGER NOT NULL DEFAULT 0,
  hpp_dipertahankan INTEGER NOT NULL DEFAULT 0,  -- HPP D1 dibiarkan krn Kledo 0/kosong
  stok_baris     INTEGER NOT NULL DEFAULT 0,     -- baris stock_by_bin yang ditulis
  stok_drift     INTEGER NOT NULL DEFAULT 0,     -- produk yang qty-nya berbeda dari D1
  galat          INTEGER NOT NULL DEFAULT 0,
  durasi_ms      INTEGER,
  pesan          TEXT,
  oleh           TEXT
);
CREATE TABLE kledo_sync_galat (
  id       INTEGER PRIMARY KEY AUTOINCREMENT,
  sync_id  INTEGER NOT NULL REFERENCES kledo_sync(id) ON DELETE CASCADE,
  bagian   TEXT NOT NULL,      -- kredensial|gudang|produk|stok
  ref      TEXT,               -- kledo_id / sku / nama gudang
  pesan    TEXT NOT NULL,
  at       INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE shopee_produk (
  kode_produk TEXT NOT NULL,
  sku TEXT NOT NULL,
  tingkat TEXT NOT NULL CHECK (tingkat IN ('variasi','induk')),
  variasi TEXT,
  kode_variasi_shopee TEXT,
  nama_shopee TEXT,
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  PRIMARY KEY (kode_produk, sku)
);
CREATE TABLE peta_putusan (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  jenis TEXT NOT NULL CHECK (jenis IN ('tanpa_sku','sku_tak_ada_master')),
  acuan TEXT NOT NULL,
  nama_shopee TEXT,
  pesanan INTEGER NOT NULL DEFAULT 0,
  omzet INTEGER NOT NULL DEFAULT 0,
  kandidat_json TEXT NOT NULL DEFAULT '[]',
  diputuskan_sku TEXT,
  diputuskan_at INTEGER,
  diputuskan_oleh TEXT,
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  UNIQUE (jenis, acuan)
);
CREATE TABLE ads_produk (
  preset_id INTEGER NOT NULL REFERENCES seller_presets(id) ON DELETE CASCADE,
  tanggal TEXT NOT NULL,
  sku TEXT NOT NULL,
  biaya INTEGER NOT NULL DEFAULT 0,
  klik INTEGER,
  dilihat INTEGER,
  omzet_iklan INTEGER NOT NULL DEFAULT 0,
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  PRIMARY KEY (preset_id, tanggal, sku)
);
CREATE TABLE performa_produk (
  preset_id INTEGER NOT NULL REFERENCES seller_presets(id) ON DELETE CASCADE,
  periode TEXT NOT NULL,
  sku TEXT NOT NULL,
  dilihat INTEGER NOT NULL DEFAULT 0,
  klik INTEGER NOT NULL DEFAULT 0,
  kunjungan INTEGER NOT NULL DEFAULT 0,
  keranjang INTEGER NOT NULL DEFAULT 0,
  pesanan INTEGER NOT NULL DEFAULT 0,
  omzet INTEGER NOT NULL DEFAULT 0,
  melihat_tanpa_beli INTEGER NOT NULL DEFAULT 0,
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  PRIMARY KEY (preset_id, periode, sku)
);
CREATE TABLE desain_folder (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  preset_id INTEGER NOT NULL REFERENCES seller_presets(id) ON DELETE CASCADE,
  nama TEXT NOT NULL,
  parent_id INTEGER REFERENCES desain_folder(id) ON DELETE CASCADE,
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  oleh TEXT
);
CREATE TABLE ai_latar (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  preset_id INTEGER NOT NULL REFERENCES seller_presets(id) ON DELETE CASCADE,
  folder_id INTEGER REFERENCES desain_folder(id) ON DELETE SET NULL,
  nama TEXT NOT NULL DEFAULT 'Latar',
  mime TEXT NOT NULL,
  base64 TEXT NOT NULL,
  byte INTEGER NOT NULL DEFAULT 0,
  folder_manual INTEGER NOT NULL DEFAULT 0,
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  oleh TEXT
);
CREATE TABLE ai_desain (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  preset_id INTEGER NOT NULL REFERENCES seller_presets(id) ON DELETE CASCADE,
  folder_id INTEGER REFERENCES desain_folder(id) ON DELETE SET NULL,
  nama TEXT NOT NULL DEFAULT 'Tanpa nama',
  ukuran TEXT NOT NULL,
  dokumen_json TEXT NOT NULL DEFAULT '{}',
  latar_id INTEGER REFERENCES ai_latar(id) ON DELETE SET NULL,
  at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),
  oleh TEXT
);
CREATE TABLE ai_analisa_setting (
  tg_id         TEXT PRIMARY KEY,
  reasoning     TEXT NOT NULL DEFAULT '',              -- '' = default model; nilai sah dari ai_model.reasoning_pilihan
  maks_token    INTEGER NOT NULL DEFAULT 16000,        -- plafon LONGGAR; cegah balasan 'incomplete' yang tokennya tetap terbayar
  kedalaman     TEXT NOT NULL DEFAULT 'sedang' CHECK (kedalaman IN ('ringkas','sedang','panjang')), -- INSTRUKSI panjang, bukan pemotongan output
  diperbarui_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE picklist_ekspor (
  marketplace  TEXT NOT NULL,
  no_pesanan   TEXT NOT NULL,
  mode         TEXT NOT NULL CHECK (mode IN ('per_paket','pisah','gabung','gabung-order')),
  at           INTEGER NOT NULL DEFAULT (unixepoch()),  -- unixepoch detik; diperbarui tiap cetak ulang
  oleh         TEXT,                                    -- id user pencetak terakhir; NULL = jalur tanpa user
  jumlah_cetak INTEGER NOT NULL DEFAULT 1,              -- >1 = cetak ulang; bukti saat sengketa
  PRIMARY KEY (marketplace, no_pesanan, mode)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX idx_sessions_expires ON sessions(expires_at) WHERE revoked_at IS NULL;
CREATE INDEX idx_codes_tg ON auth_codes(tg_id, purpose, expires_at);
CREATE INDEX idx_audit_tg ON login_audit(tg_id, at DESC);
CREATE INDEX idx_products_online ON products(is_online_product);
CREATE INDEX idx_products_norm ON products(nama_accurate_normalized);
CREATE INDEX idx_variants_sku ON product_variants(sku);
CREATE INDEX idx_mp_sku ON mp_products(sku, marketplace);
CREATE INDEX idx_sbb_sku ON stock_by_bin(sku);
CREATE INDEX idx_sbb_wh ON stock_by_bin(warehouse_id);
CREATE INDEX idx_transfers_status ON transfers(status);
CREATE INDEX idx_dest_wh ON transfer_destinations(dest_warehouse_id, status_kirim);
CREATE INDEX idx_dest_transfer ON transfer_destinations(transfer_id);
CREATE INDEX idx_titem_dest ON transfer_items(destination_id);
CREATE INDEX idx_tlog_transfer ON transfer_status_log(transfer_id);
CREATE INDEX idx_counts_status ON stock_counts(status, warehouse_id);
CREATE INDEX idx_clines_count ON count_lines(count_id);
CREATE INDEX idx_dritem_tanggal ON daily_request_items(tanggal);
CREATE INDEX idx_drch_tanggal ON daily_request_changes(tanggal, id DESC);
CREATE INDEX idx_access_status ON access_requests(status);
CREATE INDEX idx_keyword_last_used ON keyword_notes(last_used DESC);
CREATE INDEX idx_pch_sku ON product_changes(sku, at DESC);
CREATE INDEX idx_arch_tg ON admin_role_changes(tg_id, at DESC);
CREATE INDEX idx_queue_pending ON notify_queue(sent_at, created_at);
CREATE INDEX idx_import_status ON import_batches(status, at DESC);
CREATE INDEX idx_import_err ON import_errors(batch_id);
CREATE INDEX idx_orders_tgl ON orders(tanggal);
CREATE INDEX idx_orders_mp ON orders(marketplace, tanggal);
CREATE INDEX idx_orders_resi ON orders(no_resi);
CREATE INDEX idx_users_tg ON users(tg_id);
CREATE INDEX idx_users_active ON users(id) WHERE active = 1;
CREATE INDEX idx_users_role ON users(role);
CREATE INDEX idx_uw_warehouse ON user_warehouses(warehouse_id);
CREATE INDEX idx_presets_aktif ON seller_presets(aktif) WHERE dihapus_at IS NULL;
CREATE INDEX idx_fee_rules_preset ON fee_rules(preset_id, jenis, kategori);
CREATE INDEX idx_laba_snapshot_tgl ON laba_snapshot(tanggal);
CREATE INDEX idx_laba_order_tgl ON laba_order(preset_id, tanggal_snapshot);
CREATE INDEX idx_laba_order_pesanan ON laba_order(preset_id, tanggal_pesanan);
CREATE INDEX idx_advance_status ON advance_bookings(status);
CREATE INDEX idx_advance_batch ON advance_bookings(batch_import);
CREATE INDEX idx_advance_resi ON advance_bookings(no_resi);
CREATE UNIQUE INDEX idx_import_files_hash ON import_files(tipe, file_hash);
CREATE INDEX idx_resi_grup_jumlah ON resi_grup(jumlah_order);
CREATE INDEX idx_resigrup_tipe ON resi_grup(tipe_pesanan);
CREATE INDEX idx_items_sku ON order_items(sku);
CREATE INDEX idx_moves_sku ON stock_moves(sku, at DESC);
CREATE INDEX idx_moves_pending ON stock_moves(status) WHERE status != 'processed';
CREATE INDEX idx_moves_gudang ON stock_moves(gudang_id, at DESC);
CREATE INDEX idx_ai_kred_provider ON ai_kredensial(provider, aktif);
CREATE INDEX idx_ai_model_prov ON ai_model(provider, jenis, aktif);
CREATE INDEX idx_ai_preset_kat ON ai_preset_prompt(kategori, urutan);
CREATE INDEX idx_ai_kata ON ai_tool_kata(kata, aktif);
CREATE UNIQUE INDEX idx_users_username
  ON users(lower(username)) WHERE username IS NOT NULL AND username != '';
CREATE INDEX idx_kledo_map_lokal ON kledo_map(lokal_id);
CREATE INDEX idx_kledo_sync_mulai ON kledo_sync(mulai_at DESC);
CREATE INDEX idx_kledo_galat_sync ON kledo_sync_galat(sync_id);
CREATE UNIQUE INDEX idx_wh_kledo ON warehouses(kledo_id) WHERE kledo_id IS NOT NULL;
CREATE INDEX idx_products_kledo_sync ON products(kledo_synced_at);
CREATE INDEX idx_shopee_produk_sku ON shopee_produk(sku);
CREATE INDEX idx_shopee_produk_tingkat ON shopee_produk(kode_produk, tingkat);
CREATE INDEX idx_peta_putusan_belum ON peta_putusan(pesanan DESC) WHERE diputuskan_at IS NULL;
CREATE INDEX idx_ads_produk_tgl ON ads_produk(preset_id, tanggal);
CREATE INDEX idx_desain_folder_pohon ON desain_folder(preset_id, parent_id);
CREATE INDEX idx_ai_latar_daftar ON ai_latar(preset_id, at DESC);
CREATE INDEX idx_ai_desain_terbaru ON ai_desain(preset_id, updated_at DESC);
CREATE INDEX idx_ai_desain_folder ON ai_desain(folder_id);
CREATE INDEX idx_items_perlu_sku ON order_items(perlu_sku) WHERE perlu_sku = 1;
CREATE INDEX idx_picklist_ekspor_order ON picklist_ekspor (marketplace, no_pesanan);
